CREATE TABLE IF NOT EXISTS tenants (
	id BIGSERIAL NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	subdomain_or_code VARCHAR(100) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_tenants_id ON tenants (id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_tenants_name ON tenants (name);
CREATE UNIQUE INDEX IF NOT EXISTS ix_tenants_subdomain_or_code ON tenants (subdomain_or_code);

CREATE TABLE IF NOT EXISTS categories (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description VARCHAR(255), 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uix_tenant_category_name UNIQUE (tenant_id, name), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_categories_id ON categories (id);
CREATE INDEX IF NOT EXISTS ix_categories_tenant_id ON categories (tenant_id);

CREATE TABLE IF NOT EXISTS customer_orders (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	order_number VARCHAR(50) NOT NULL, 
	customer_name VARCHAR(100) NOT NULL, 
	order_type VARCHAR(50) NOT NULL, 
	table_number VARCHAR(50), 
	notes TEXT, 
	total_amount NUMERIC(10, 2) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	tracking_token VARCHAR(64), 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_customer_orders_id ON customer_orders (id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_customer_orders_order_number ON customer_orders (order_number);
CREATE INDEX IF NOT EXISTS ix_customer_orders_tracking_token ON customer_orders (tracking_token);

CREATE TABLE IF NOT EXISTS inventory_items (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	category VARCHAR(100), 
	sku VARCHAR(50), 
	quantity NUMERIC(10, 2) NOT NULL, 
	unit VARCHAR(20) NOT NULL, 
	min_stock NUMERIC(10, 2) NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uix_tenant_inventory_name UNIQUE (tenant_id, name), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_inventory_items_id ON inventory_items (id);

CREATE TABLE IF NOT EXISTS restaurant_tables (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	table_number VARCHAR(50) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_restaurant_tables_id ON restaurant_tables (id);
CREATE INDEX IF NOT EXISTS ix_restaurant_tables_tenant_id ON restaurant_tables (tenant_id);

CREATE TABLE IF NOT EXISTS suppliers (
	id BIGSERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	supplier_name VARCHAR(150) NOT NULL, 
	contact_number VARCHAR(50), 
	category VARCHAR(100), 
	contact_person VARCHAR(100), 
	email VARCHAR(100), 
	address TEXT, 
	products_supplied VARCHAR(255), 
	status VARCHAR(50) NOT NULL, 
	notes TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uix_tenant_supplier_name UNIQUE (tenant_id, supplier_name), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_suppliers_id ON suppliers (id);
CREATE INDEX IF NOT EXISTS ix_suppliers_tenant_id ON suppliers (tenant_id);

CREATE TABLE IF NOT EXISTS users (
	id SERIAL NOT NULL, 
	tenant_id BIGINT, 
	username VARCHAR(50) NOT NULL, 
	first_name VARCHAR(50), 
	last_name VARCHAR(50), 
	email VARCHAR(100), 
	phone VARCHAR(30), 
	password_hash VARCHAR(255) NOT NULL, 
	role userrole NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	token_version INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_users_email ON users (email);
CREATE INDEX IF NOT EXISTS ix_users_id ON users (id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_users_username ON users (username);

CREATE TABLE IF NOT EXISTS activity_logs (
	id BIGSERIAL NOT NULL, 
	tenant_id BIGINT, 
	user_id INTEGER, 
	action VARCHAR(50) NOT NULL, 
	performed_by VARCHAR(100) NOT NULL, 
	target_user VARCHAR(100), 
	role VARCHAR(50), 
	details VARCHAR(255), 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_activity_logs_created_at ON activity_logs (created_at);
CREATE INDEX IF NOT EXISTS ix_activity_logs_id ON activity_logs (id);
CREATE INDEX IF NOT EXISTS ix_activity_logs_tenant_id ON activity_logs (tenant_id);
CREATE INDEX IF NOT EXISTS ix_activity_logs_user_id ON activity_logs (user_id);

CREATE TABLE IF NOT EXISTS expenses (
