CREATE INDEX IF NOT EXISTS ix_incident_reports_user_id ON incident_reports (user_id);

CREATE TABLE IF NOT EXISTS products (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	category_id INTEGER, 
	name VARCHAR(100) NOT NULL, 
	sku VARCHAR(50) NOT NULL, 
	barcode VARCHAR(100), 
	price NUMERIC(10, 2) NOT NULL, 
	cost NUMERIC(10, 2) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	image_url TEXT, 
	preparation_station VARCHAR(30) DEFAULT 'kitchen' NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uix_tenant_product_sku UNIQUE (tenant_id, sku), 
	CONSTRAINT uix_tenant_product_name UNIQUE (tenant_id, name), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(category_id) REFERENCES categories (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_products_barcode ON products (barcode);
CREATE INDEX IF NOT EXISTS ix_products_category_id ON products (category_id);
CREATE INDEX IF NOT EXISTS ix_products_id ON products (id);
CREATE INDEX IF NOT EXISTS ix_products_is_active ON products (is_active);
CREATE INDEX IF NOT EXISTS ix_products_tenant_id ON products (tenant_id);

CREATE TABLE IF NOT EXISTS purchase_orders (
	id BIGSERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	po_number VARCHAR(50) NOT NULL, 
	supplier_id BIGINT NOT NULL, 
	order_date TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	expected_delivery_date TIMESTAMP WITHOUT TIME ZONE, 
	received_date TIMESTAMP WITHOUT TIME ZONE, 
	status purchaseorderstatus NOT NULL, 
	subtotal NUMERIC(10, 2) NOT NULL, 
	total_amount NUMERIC(10, 2) NOT NULL, 
	notes TEXT, 
	created_by INTEGER, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uix_tenant_po_number UNIQUE (tenant_id, po_number), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(supplier_id) REFERENCES suppliers (id) ON DELETE RESTRICT, 
	FOREIGN KEY(created_by) REFERENCES users (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_purchase_orders_id ON purchase_orders (id);
CREATE INDEX IF NOT EXISTS ix_purchase_orders_po_number ON purchase_orders (po_number);
CREATE INDEX IF NOT EXISTS ix_purchase_orders_supplier_id ON purchase_orders (supplier_id);
CREATE INDEX IF NOT EXISTS ix_purchase_orders_tenant_id ON purchase_orders (tenant_id);

CREATE TABLE IF NOT EXISTS shifts (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	user_id INTEGER NOT NULL, 
	start_time TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	end_time TIMESTAMP WITHOUT TIME ZONE, 
	start_cash NUMERIC(10, 2) NOT NULL, 
	end_cash NUMERIC(10, 2), 
	status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS ix_shifts_id ON shifts (id);
CREATE INDEX IF NOT EXISTS ix_shifts_start_time ON shifts (start_time);
CREATE INDEX IF NOT EXISTS ix_shifts_status ON shifts (status);
CREATE INDEX IF NOT EXISTS ix_shifts_tenant_id ON shifts (tenant_id);
CREATE INDEX IF NOT EXISTS ix_shifts_user_id ON shifts (user_id);

CREATE TABLE IF NOT EXISTS customer_order_items (
	id SERIAL NOT NULL, 
	customer_order_id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	variant VARCHAR(100), 
	price NUMERIC(10, 2) NOT NULL, 
	quantity INTEGER NOT NULL, 
	product_id INTEGER, 
	PRIMARY KEY (id), 
	FOREIGN KEY(customer_order_id) REFERENCES customer_orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_customer_order_items_id ON customer_order_items (id);

CREATE TABLE IF NOT EXISTS product_recipes (
	id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	inventory_item_id INTEGER NOT NULL, 
	quantity NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uix_product_inventory UNIQUE (product_id, inventory_item_id), 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE CASCADE, 
	FOREIGN KEY(inventory_item_id) REFERENCES inventory_items (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_product_recipes_id ON product_recipes (id);
CREATE INDEX IF NOT EXISTS ix_product_recipes_inventory_item_id ON product_recipes (inventory_item_id);
CREATE INDEX IF NOT EXISTS ix_product_recipes_product_id ON product_recipes (product_id);

CREATE TABLE IF NOT EXISTS purchase_order_items (
	id BIGSERIAL NOT NULL, 
	purchase_order_id BIGINT NOT NULL, 
	inventory_item_id INTEGER NOT NULL, 
	quantity NUMERIC(10, 2) NOT NULL, 
	unit_cost NUMERIC(10, 2) NOT NULL, 
	total_cost NUMERIC(10, 2) NOT NULL, 
	notes TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders (id) ON DELETE CASCADE, 
	FOREIGN KEY(inventory_item_id) REFERENCES inventory_items (id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS ix_purchase_order_items_id ON purchase_order_items (id);
CREATE INDEX IF NOT EXISTS ix_purchase_order_items_purchase_order_id ON purchase_order_items (purchase_order_id);

CREATE TABLE IF NOT EXISTS shift_cash_movements (
	id BIGSERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	shift_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	type VARCHAR(20) NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	reason VARCHAR(255), 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT check_movement_type CHECK (type IN ('PAID_IN', 'PAID_OUT')), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(shift_id) REFERENCES shifts (id) ON DELETE CASCADE, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_shift_cash_movements_created_at ON shift_cash_movements (created_at);
CREATE INDEX IF NOT EXISTS ix_shift_cash_movements_id ON shift_cash_movements (id);
CREATE INDEX IF NOT EXISTS ix_shift_cash_movements_shift_id ON shift_cash_movements (shift_id);
CREATE INDEX IF NOT EXISTS ix_shift_cash_movements_tenant_id ON shift_cash_movements (tenant_id);
CREATE INDEX IF NOT EXISTS ix_shift_cash_movements_type ON shift_cash_movements (type);
CREATE INDEX IF NOT EXISTS ix_shift_cash_movements_user_id ON shift_cash_movements (user_id);

CREATE TABLE IF NOT EXISTS transactions (
	id SERIAL NOT NULL, 
	tenant_id BIGINT NOT NULL, 
	shift_id INTEGER NOT NULL, 
	user_id INTEGER NOT NULL, 
	client_tx_id VARCHAR(36), 
	total_amount NUMERIC(10, 2) NOT NULL, 
	tax_amount NUMERIC(10, 2) NOT NULL, 
	discount_amount NUMERIC(10, 2) NOT NULL, 
	net_amount NUMERIC(10, 2) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	fulfillment_status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(shift_id) REFERENCES shifts (id) ON DELETE RESTRICT, 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS ix_transactions_client_tx_id ON transactions (client_tx_id);
CREATE INDEX IF NOT EXISTS ix_transactions_created_at ON transactions (created_at);
CREATE INDEX IF NOT EXISTS ix_transactions_fulfillment_status ON transactions (fulfillment_status);
CREATE INDEX IF NOT EXISTS ix_transactions_id ON transactions (id);
CREATE INDEX IF NOT EXISTS ix_transactions_shift_id ON transactions (shift_id);
CREATE INDEX IF NOT EXISTS ix_transactions_status ON transactions (status);
CREATE INDEX IF NOT EXISTS ix_transactions_tenant_id ON transactions (tenant_id);
CREATE INDEX IF NOT EXISTS ix_transactions_user_id ON transactions (user_id);

CREATE TABLE IF NOT EXISTS payments (
	id SERIAL NOT NULL, 
	transaction_id INTEGER NOT NULL, 
	payment_method VARCHAR(50) NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(transaction_id) REFERENCES transactions (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_payments_created_at ON payments (created_at);
CREATE INDEX IF NOT EXISTS ix_payments_id ON payments (id);
CREATE INDEX IF NOT EXISTS ix_payments_payment_method ON payments (payment_method);
CREATE INDEX IF NOT EXISTS ix_payments_status ON payments (status);
CREATE INDEX IF NOT EXISTS ix_payments_transaction_id ON payments (transaction_id);

CREATE TABLE IF NOT EXISTS transaction_items (
	id SERIAL NOT NULL, 
	transaction_id INTEGER NOT NULL, 
	product_id INTEGER, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	total_price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(transaction_id) REFERENCES transactions (id) ON DELETE CASCADE, 
	FOREIGN KEY(product_id) REFERENCES products (id) ON DELETE SET NULL
);

CREATE INDEX IF NOT EXISTS ix_transaction_items_id ON transaction_items (id);
CREATE INDEX IF NOT EXISTS ix_transaction_items_product_id ON transaction_items (product_id);
CREATE INDEX IF NOT EXISTS ix_transaction_items_transaction_id ON transaction_items (transaction_id);

